const setDispatch = `-- name: SetDispatch :exec
UPDATE delivery_notes
SET recipient_name = ?,
    recipient_signature_status = ?,
    recipient_signature_missing_reason = ?,
    dispatched_at = ?, dispatched_by = ?,
    confirmed_at = ?, confirmed_by = ?,
    updated_at = ?, updated_by = ?
WHERE id = ?
`

type SetDispatchParams struct {
	RecipientName sql.NullString
	SigStatus     sql.NullString
	SigReason     sql.NullString
	Stamp         sql.NullTime
	ActorID       sql.NullInt64
	Now           time.Time
	ID            int64
}

// Stamps the dispatch + confirm event without flipping the status.
func (q *Queries) SetDispatch(ctx context.Context, arg SetDispatchParams) error {
	_, err := q.db.ExecContext(ctx, setDispatch,
		arg.RecipientName,
		arg.SigStatus,
		arg.SigReason,
		arg.Stamp,
		arg.ActorID,
		arg.Stamp,
		arg.ActorID,
		arg.Now,
		arg.ActorID,
		arg.ID,
	)
	return err
}

const setNoteStatus = `-- name: SetNoteStatus :exec
UPDATE delivery_notes
SET status = ?, updated_at = ?, updated_by = ? WHERE id = ?
`

type SetNoteStatusParams struct {
	Status    string
	Now       time.Time
	UpdatedBy sql.NullInt64
	ID        int64
}

func (q *Queries) SetNoteStatus(ctx context.Context, arg SetNoteStatusParams) error {
	_, err := q.db.ExecContext(ctx, setNoteStatus,
		arg.Status,
		arg.Now,
		arg.UpdatedBy,
		arg.ID,
	)
	return err
}

const transitionNote = `-- name: TransitionNote :execresult
UPDATE delivery_notes
SET status = ?, updated_at = ?, updated_by = ?
WHERE id = ? AND status IN (/*SLICE:from_statuses*/?)
`

type TransitionNoteParams struct {
	ToStatus     string
	Now          time.Time
	ActorID      sql.NullInt64
	ID           int64
	FromStatuses []string
}

// CAS: moves the status only from one of the allowed origins.
func (q *Queries) TransitionNote(ctx context.Context, arg TransitionNoteParams) (sql.Result, error) {
	query := transitionNote
	var queryParams []interface{}
	queryParams = append(queryParams, arg.ToStatus)
	queryParams = append(queryParams, arg.Now)
	queryParams = append(queryParams, arg.ActorID)
	queryParams = append(queryParams, arg.ID)
	if len(arg.FromStatuses) > 0 {
		for _, v := range arg.FromStatuses {
			queryParams = append(queryParams, v)
		}
		query = strings.Replace(query, "/*SLICE:from_statuses*/?", strings.Repeat(",?", len(arg.FromStatuses))[1:], 1)
	} else {
		query = strings.Replace(query, "/*SLICE:from_statuses*/?", "NULL", 1)
	}
	return q.db.ExecContext(ctx, query, queryParams...)
}
